  de = {
    [265] = "Fliegt über die Die Sturmgipfel, erscheint alle 6-24 Stunden (stattdessen kann Vyragosa kommen). Das Reittier fällt immer.",
    [393] = "Fliegt über Tiefenheim; erscheint alle paar Stunden, man muss ihn besteigen und besiegen. Das Reittier fällt immer.",
